func TestBillable(t *testing.T) {
	cases := []struct {
		name    string
		in      []string
		want    time.Duration
		wantErr bool
	}{
		{"kosong", nil, 0, false},
		{"tepat kelipatan", []string{"1h", "30m"}, 90 * time.Minute, false},
		{"bulatkan ke atas", []string{"10m", "2m"}, 15 * time.Minute, false},
		{"sisa detik", []string{"1m1s"}, 15 * time.Minute, false},
		{"lintas jam", []string{"50m", "20m"}, 75 * time.Minute, false},
		{"tepat 15 menit", []string{"7m30s", "7m30s"}, 15 * time.Minute, false},
		{"lewat satu detik", []string{"15m1s"}, 30 * time.Minute, false},
		{"nol", []string{"0s"}, 0, false},
		{"format salah", []string{"1jam"}, 0, true},
		{"negatif", []string{"30m", "-5m"}, 0, true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, err := Billable(c.in)
			if c.wantErr {
				if err == nil {
					t.Fatalf("Billable(%q) error = nil, want error", c.in)
				}
				if got != 0 {
					t.Errorf("Billable(%q) = %v on error, want 0", c.in, got)
				}
				return
			}
			if err != nil {
				t.Fatalf("Billable(%q) error = %v, want nil", c.in, err)
			}
			if got != c.want {
				t.Fatalf("Billable(%q) = %v, want %v", c.in, got, c.want)
			}
		})
	}
}

