package timesheet

import (
	"fmt"
	"time"
)

// Billable sums the duration entries (e.g. "1h30m", "45m") and rounds the
// total UP to the next 15-minute block. Invalid or negative entries return
// 0 and a non-nil error.
func Billable(entries []string) (time.Duration, error) {
	var total time.Duration
	for _, e := range entries {
		d, err := time.ParseDuration(e)
		if err != nil {
			return 0, fmt.Errorf("entry %q: %w", e, err)
		}
		if d < 0 {
			return 0, fmt.Errorf("entry %q: durasi negatif", e)
		}
		total += d
	}
	const block = 15 * time.Minute
	if rem := total % block; rem != 0 {
		total += block - rem
	}
	return total, nil
}
